mapper.select:
SELECT id, user_id, credential_generation, new_email, token_hash, expires_at, consumed_at, requested_ip, created_at
FROM email_change_token
WHERE token_hash = #{tokenHash}

SELECT COUNT(*) FROM email_change_token
WHERE user_id = #{userId}
  AND created_at > DATE_SUB(UTC_TIMESTAMP(), INTERVAL #{withinSeconds} SECOND)
